components.css:
.ds-button-primary {font-family: 'Plus Jakarta Sans', system-ui, sans-serif;}
.ds-button-primary {min-height: 44px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; border-radius: 12px; font-size: 12px; font-weight: 700; line-height: 1.4; padding: 11px 17px; white-space: nowrap; border: 1.5px solid transparent;}
.ds-button-primary:active:not(:disabled) {transform: translateY(1px);}
.ds-primary {color: var(--on-accent, #264550); background: var(--accent, #f7d070); border-color: var(--outline, #315966); box-shadow: 0 3px 0 var(--outline, #315966);}
.ds-primary:hover:not(:disabled) {background: var(--accent-hover, #fbe09a); transform: translateY(-1px); box-shadow: 0 4px 0 var(--outline, #315966);}
.ds-button-primary {cursor: pointer;transition: color 180ms ease, background-color 180ms ease, border-color 180ms ease, transform 180ms ease, box-shadow 180ms ease;}.ds-button-primary:focus-visible {outline: 3px solid var(--outline, #315966); outline-offset: 4px;}.ds-button-primary:disabled {cursor: not-allowed; opacity: .55;}

.ds-button-outline {font-family: 'Plus Jakarta Sans', system-ui, sans-serif;}
.ds-button-outline {min-height: 44px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; border-radius: 12px; font-size: 12px; font-weight: 700; line-height: 1.4; padding: 11px 17px; white-space: nowrap; border: 1.5px solid transparent;}
.ds-button-outline:active:not(:disabled) {transform: translateY(1px);}
.ds-outline {background: var(--surface, #fbfdfc); color: var(--ink, #254c59); border-color: var(--line, #c4d8dc);}
.ds-outline:hover:not(:disabled) {border-color: var(--outline, #315966); background: var(--subtle, #e3eeee);}
.ds-button-outline {cursor: pointer;transition: color 180ms ease, background-color 180ms ease, border-color 180ms ease, transform 180ms ease, box-shadow 180ms ease;}.ds-button-outline:focus-visible {outline: 3px solid var(--outline, #315966); outline-offset: 4px;}.ds-button-outline:disabled {cursor: not-allowed; opacity: .55;}

.ds-search-field {font-family: 'Plus Jakarta Sans', system-ui, sans-serif;}
.ds-search-field {display: flex; align-items: center; gap: 9px; border: 1px solid var(--line, #c4d8dc); background: var(--surface, #fbfdfc); color: var(--muted, #526b73); padding: 0 12px; border-radius: 11px; min-width: 0;}
.ds-search-field:focus-within {outline: 2px solid var(--outline, #315966); outline-offset: 2px;}
.ds-search-field input {width: 100%; min-width: 0; border: 0; outline: none; font-size: 11px; padding: 12px 0; background: transparent; min-height: 44px;}
.ds-search-field input:focus-visible {outline: none;}
.ds-search-field input {font-family: inherit; color: var(--ink, #254c59); caret-color: var(--ink, #254c59);}.ds-search-field input::placeholder {color: var(--muted, #526b73); opacity: 1;}.ds-search-field svg {flex-shrink: 0;}.ds-search-field input:disabled {opacity: .65;}
@media (max-width: 767px) {
.ds-search-field input {font-size: 16px;}
}

.ds-site-header {font-family: 'Plus Jakarta Sans', system-ui, sans-serif;}
.ds-site-header {position: sticky; top: 0; z-index: 10; background: var(--canvas, #edf5f5); border-bottom: 1px solid var(--line, #c4d8dc);}
.ds-nav-inner {height: 80px; display: flex; align-items: center; justify-content: space-between; gap: 24px;}
.ds-brand {display: inline-flex; align-items: center; gap: 11px; flex-shrink: 0;}
.ds-brand-mark {height: 40px; width: 40px; display: grid; place-items: center; background: var(--accent, #f7d070); color: var(--on-accent, #264550); border: 1.5px solid var(--outline, #315966); border-radius: 13px; box-shadow: 0 3px 0 var(--outline, #315966);}
.ds-brand-name {font-size: 21px; letter-spacing: -.8px; font-weight: 800; white-space: nowrap;}
.ds-brand-name > span {font-weight: 500;}
.ds-nav-actions {display: flex; align-items: center; gap: 10px;}
.ds-button {min-height: 44px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; border-radius: 12px; font-size: 12px; font-weight: 700; line-height: 1.4; padding: 11px 17px; white-space: nowrap; border: 1.5px solid transparent;}
.ds-button:active:not(:disabled), .ds-icon-button:active:not(:disabled) {transform: translateY(1px);}
.ds-button-primary {color: var(--on-accent, #264550); background: var(--accent, #f7d070); border-color: var(--outline, #315966); box-shadow: 0 3px 0 var(--outline, #315966);}
.ds-button-primary:hover:not(:disabled) {background: var(--accent-hover, #fbe09a); transform: translateY(-1px); box-shadow: 0 4px 0 var(--outline, #315966);}
.ds-button-quiet {color: var(--muted, #526b73); background: transparent;}
.ds-button-quiet:hover {color: var(--ink, #254c59); background: var(--subtle, #e3eeee);}
.ds-icon-button {min-width: 40px; height: 40px; border: 0; border-radius: 10px; display: inline-flex; align-items: center; justify-content: center; color: var(--muted, #526b73); background: transparent;}
.ds-icon-button:hover {color: var(--ink, #254c59); background: var(--subtle, #e3eeee);}
.ds-nav-inner {width: min(calc(100% - 32px), 1240px); margin-inline: auto;}.ds-brand {color: var(--ink, #254c59); text-decoration: none;}.ds-nav-actions button {font-family: inherit; cursor: pointer;transition: color 180ms ease, background-color 180ms ease, border-color 180ms ease, transform 180ms ease, box-shadow 180ms ease;}.ds-brand:focus-visible, .ds-nav-actions button:focus-visible {outline: 3px solid var(--outline, #315966); outline-offset: 4px;}.ds-nav-actions button:disabled {cursor: not-allowed; opacity: .55;}
@media (max-width: 767px) {
.ds-nav-inner {height: 70px; gap: 12px;}
.ds-brand {gap: 8px;}
.ds-brand-name {font-size: 18px; letter-spacing: -.7px;}
.ds-brand-mark {width: 34px; height: 34px; border-radius: 10px;}
.ds-stats-toggle span {display: none;}
.ds-nav-actions {gap: 4px;}
.ds-nav-actions .ds-button {padding: 9px 11px; font-size: 11px;}
.ds-stats-toggle {width: 40px;}
.ds-theme-button {min-width: 36px;}
}
@media (max-width: 380px) {
.ds-brand-name {font-size: 16px;}
.ds-brand-mark {width: 30px; height: 30px;}
.ds-nav-actions .ds-batch-button {padding-inline: 9px;}
.ds-theme-button {min-width: 30px;}
}
@media (pointer: coarse) {
.ds-icon-button {min-width: 44px; height: 44px;}
}

.ds-locked-category {font-family: 'Plus Jakarta Sans', system-ui, sans-serif;}
.ds-locked-category {background: var(--subtle, #e3eeee); color: var(--ink, #254c59); font-size: 10px; border: 1px solid var(--line, #c4d8dc); border-radius: 7px; padding: 7px 8px; min-width: 0; max-width: 100%; text-overflow: ellipsis; min-height: 32px;}
.ds-locked-category {display: inline-flex; align-items: center; gap: 5px;}

@media (max-width: 767px) {
.ds-locked-category {font-size: 11px;}
}

.ds-source-tab {font-family: 'Plus Jakarta Sans', system-ui, sans-serif;}
.ds-source-tab {display: flex; align-items: center; justify-content: center; gap: 10px; padding: 13px 15px; min-height: 52px; border: 1px solid var(--line, #c4d8dc); border-radius: 13px; font-size: 12px; font-weight: 600; color: var(--muted, #526b73); background: transparent;}
.ds-source-tab:hover {border-color: var(--outline, #315966); color: var(--ink, #254c59); background: var(--subtle, #e3eeee);}
.ds-source-tab.ds-is-selected {background: var(--surface, #fbfdfc); color: var(--ink, #254c59); border: 1.5px solid var(--outline, #315966); box-shadow: 0 3px 0 var(--outline, #315966); font-weight: 700;}
.ds-source-count {font-size: 10px; font-weight: 700; font-variant-numeric: tabular-nums; min-width: 23px; padding: 3px 6px; border-radius: 6px; background: var(--subtle, #e3eeee); color: var(--ink, #254c59);}
.ds-source-tab.ds-is-selected .ds-source-count {background: var(--accent, #f7d070); color: var(--on-accent, #264550);}
.ds-source-tab {cursor: pointer;transition: color 180ms ease, background-color 180ms ease, border-color 180ms ease, transform 180ms ease, box-shadow 180ms ease;}.ds-source-tab:focus-visible {outline: 3px solid var(--outline, #315966); outline-offset: 4px;}.ds-source-tab:disabled {cursor: not-allowed; opacity: .55;}
@media (max-width: 767px) {
.ds-source-tab {min-height: 48px; padding: 10px 9px; font-size: 10px; gap: 7px;}
.ds-source-tab svg {width: 16px; height: 16px;}
.ds-source-count {margin-left: auto; font-size: 9px;}
}

.ds-link-card {font-family: 'Plus Jakarta Sans', system-ui, sans-serif;}
.ds-icon-button:active:not(:disabled) {transform: translateY(1px);}
.ds-icon-button {min-width: 40px; height: 40px; border: 0; border-radius: 10px; display: inline-flex; align-items: center; justify-content: center; color: var(--muted, #526b73); background: transparent;}
.ds-icon-button:hover {color: var(--ink, #254c59); background: var(--subtle, #e3eeee);}
.ds-link-card {min-width: 0; display: flex; flex-direction: column; background: var(--surface, #fbfdfc); border: 1px solid var(--line, #c4d8dc); border-radius: 18px; padding: 21px 21px 8px; box-shadow: 0 3px 0 var(--shadow, #c4d8dc); transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease; content-visibility: auto; contain-intrinsic-size: auto 355px;}
.ds-link-card:hover {transform: translateY(-2px); border-color: var(--outline, #315966); box-shadow: 0 5px 0 var(--shadow, #c4d8dc);}
.ds-card-top {display: flex; align-items: center; justify-content: space-between; margin-bottom: 17px; gap: 12px;}
.ds-source-identity {display: flex; gap: 10px; align-items: center; min-width: 0;}
.ds-source-identity > div {min-width: 0;}
.ds-source-icon {display: grid; place-items: center; width: 42px; height: 42px; border-radius: 12px; background: var(--sky, #cee8ec);}
.ds-link-card[data-platform='drive'] .ds-source-icon {background: var(--yellow, #f8edc9);}
.ds-link-card[data-platform='web'] .ds-source-icon {background: var(--subtle, #e3eeee);}
.ds-source-name {display: block; font-size: 11px; font-weight: 700;}
.ds-source-host {display: block; font-size: 10px; color: var(--muted, #526b73); margin-top: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;}
.ds-open-link {border: 1px solid var(--line, #c4d8dc); width: 32px; min-width: 32px; height: 32px; border-radius: 9px;}
.ds-card-title {font-size: 15px; font-weight: 800; line-height: 1.55; letter-spacing: -.3px; margin-bottom: 7px; overflow-wrap: anywhere;}
.ds-card-title a {display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;}
.ds-card-title a:hover {text-decoration: underline;}
.ds-card-summary {color: var(--muted, #526b73); font-size: 11px; line-height: 1.9; overflow-wrap: anywhere; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; margin-bottom: 15px;}
.ds-card-categories {display: flex; gap: 6px; align-items: center; flex-wrap: wrap; margin-top: auto; padding-bottom: 13px;}
.ds-card-categories select, .ds-locked-category {background: var(--subtle, #e3eeee); color: var(--ink, #254c59); font-size: 10px; border: 1px solid var(--line, #c4d8dc); border-radius: 7px; padding: 7px 8px; min-width: 0; max-width: 100%; text-overflow: ellipsis; min-height: 32px;}
.ds-card-categories select {flex: 1; width: 0; min-width: 100px;}
.ds-locked-category {display: inline-flex; align-items: center; gap: 5px;}
.ds-card-categories select:last-of-type {background: transparent; border-style: dashed; color: var(--muted, #526b73);}
.ds-card-footer {display: flex; justify-content: space-between; align-items: center; gap: 4px; border-top: 1px solid var(--line, #c4d8dc); padding-top: 7px; min-height: 49px;}
.ds-card-tags {display: flex; align-items: center; gap: 9px; min-width: 0;}
.ds-card-tags button {border: 0; background: transparent; color: var(--muted, #526b73); font-size: 10px; min-height: 32px; padding: 3px 0; max-width: 104px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;}
.ds-card-tags button:hover {color: var(--ink, #254c59); text-decoration: underline;}
.ds-link-card {color: var(--ink, #254c59);}.ds-card-title {margin: 0 0 7px;}.ds-card-title a {color: inherit; text-decoration: none; text-underline-offset: 4px;}.ds-card-summary {margin-top: 0;}.ds-card-categories select {font-family: inherit; cursor: pointer;}.ds-card-tags button {font-family: inherit; cursor: pointer;}.ds-link-card a:focus-visible, .ds-link-card button:focus-visible, .ds-link-card select:focus-visible {outline: 3px solid var(--outline, #315966); outline-offset: 4px;}.ds-link-card select:disabled {opacity: .65;}.ds-source-icon svg {flex-shrink: 0;}
@media (max-width: 767px) {
.ds-link-card {padding: 20px 20px 7px;}
.ds-card-title {font-size: 16px;}
.ds-card-summary {font-size: 12px;}
.ds-source-name, .ds-card-categories select, .ds-locked-category {font-size: 11px;}
.ds-card-tags button {font-size: 11px;}
.ds-card-tags {gap: 8px;}
.ds-card-tags button {max-width: 100px;}
.ds-card-categories select {font-size: 16px;}
}
@media (pointer: coarse) {
.ds-icon-button {min-width: 44px; height: 44px;}
.ds-card-tags button {min-height: 44px;}
.ds-card-categories select {min-height: 44px;}
}
